-- 租后制度变更
CREATE TABLE `after_lease_check_change_record`
(
    `id`                   bigint(20) NOT NULL AUTO_INCREMENT,
    `plan_id`              varchar(100) DEFAULT '' COMMENT '计划id',
    `check_plan_client_id` varchar(20)  DEFAULT NULL COMMENT '计划-客户ID',
    `old_content`          varchar(255) DEFAULT NULL COMMENT '变更前内容',
    `now_content`          varchar(255) DEFAULT NULL COMMENT '变更后内容',
    `create_by`            bigint(20) DEFAULT NULL COMMENT '创建人、发起人',
    `create_time`          datetime     DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_by`            bigint(20) DEFAULT NULL COMMENT '最后更新人id',
    `update_time`          datetime     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='租后检查计划-基本信息表';

alter table `new_after_lease_check_plan_base` add column `check_way` VARCHAR(20) DEFAULT NULL COMMENT '管理形式';
alter table `new_after_lease_check_plan_base_lib` add column `check_way` VARCHAR(20) DEFAULT NULL COMMENT '管理形式';

alter table `new_after_lease_check_plan_base` add column `last_check_way` VARCHAR(20) DEFAULT NULL COMMENT '上次管理形式';
alter table `new_after_lease_check_plan_base_lib` add column `last_check_way` VARCHAR(20) DEFAULT NULL COMMENT '上次管理形式';

alter table `new_after_lease_check_plan_base` add column `last_end_date` date DEFAULT NULL COMMENT '上次结束时间';
alter table `new_after_lease_check_plan_base_lib` add column `last_end_date` date DEFAULT NULL COMMENT '上次结束时间';

alter table `new_after_lease_check_plan_base` add column `dead_line` date DEFAULT NULL COMMENT '截止时间';
alter table `new_after_lease_check_plan_base_lib` add column `dead_line` date DEFAULT NULL COMMENT '截止时间';

alter table `new_after_lease_check_plan_base` add column `term` INT(11) DEFAULT NULL COMMENT '跟进频率';
alter table `new_after_lease_check_plan_base_lib` add column `term` INT(11) DEFAULT NULL COMMENT '跟进频率';

alter table `new_after_lease_check_plan_client` add column `check_fill_time` date DEFAULT NULL COMMENT '检查填报时间';
alter table `new_after_lease_check_plan_client_lib` add column `check_fill_time` date DEFAULT NULL COMMENT '检查填报时间';

alter table `new_after_lease_check_plan_client` add column `payment_date` date DEFAULT NULL COMMENT '投放时间';
alter table `new_after_lease_check_plan_client_lib` add column `payment_date` date DEFAULT NULL COMMENT '投放时间';

ALTER TABLE `new_after_lease_check_report_base`
    MODIFY COLUMN `contract_amount` bigint(20) NULL COMMENT '合同金额' AFTER `contact_way`;

ALTER TABLE `new_after_lease_check_report_base_lib`
    MODIFY COLUMN `contract_amount` bigint(20) NULL COMMENT '合同金额' AFTER `contact_way`;




